291 | export function formatResumeCommand(sessionManager: SessionManager): string | undefined {
292 | 	if (!process.stdout.isTTY) return undefined;
293 | 	if (!sessionManager.isPersisted()) return undefined;
294 | 
295 | 	const sessionFile = sessionManager.getSessionFile();
296 | 	if (!sessionFile || !fs.existsSync(sessionFile)) return undefined;
297 | 
298 | 	const args = [APP_NAME];
299 | 	if (!sessionManager.usesDefaultSessionDir()) {
300 | 		args.push("--session-dir", quoteIfNeeded(sessionManager.getSessionDir()));
301 | 	}
302 | 	args.push("--session", sessionManager.getSessionId());
303 | 	return args.join(" ");
