441 | /** Stable reference for components while InteractiveMode replaces the active renderer. */
442 | export function createInteractiveTuiReference(getTui: () => TUI): TUI {
443 | 	return new Proxy({} as TUI, {
444 | 		get: (_target, property) => {
445 | 			const tui = getTui();
446 | 			const value = Reflect.get(tui, property, tui);
447 | 			if (typeof value !== "function") return value;
448 | 			return (...args: unknown[]) => {
449 | 				const tui = getTui();
450 | 				const method = Reflect.get(tui, property, tui);
451 | 				if (typeof method !== "function") throw new TypeError(`TUI property ${String(property)} is not callable`);
452 | 				return Reflect.apply(method, tui, args);
453 | 			};
454 | 		},
455 | 		set: (_target, property, value) => {
456 | 			const tui = getTui();
457 | 			return Reflect.set(tui, property, value, tui);
458 | 		},
459 | 		has: (_target, property) => Reflect.has(getTui(), property),
460 | 		getPrototypeOf: () => Reflect.getPrototypeOf(getTui()),
461 | 	});
462 | }
